
unsigned char crc8(unsigned char x, unsigned char k){unsigned char i; for(i=0;i<8;i++){ if(x & 0x80) x=(x<<1)^k; else x<<=1; } return x;}
int crc8s(signed char x, int k){unsigned char i; for(i=0;i<8;i++){ if(x & 0x80) x=(x<<1)^k; else x=x<<1; } return x;}
unsigned int mul(unsigned char a0, unsigned char b){unsigned int a=a0, acc=0; while(b){ if(b&1) acc+=a; a<<=1; b>>=1;} return acc;}
unsigned int crc16(unsigned int x){unsigned char i; for(i=0;i<8;i++){ if(x & 0x8000) x=(x<<1)^0x1021; else x<<=1; } return x;}
unsigned int crcr(unsigned int x){unsigned char i; for(i=0;i<8;i++){ if(x & 1) x=(x>>1)^0xA001; else x>>=1; } return x;}
unsigned int lsr(unsigned char x){unsigned int r=0; unsigned char i; for(i=0;i<8;i++){ if(x & 1) r += x>>1; else r ^= x>>1; x >>= 1;} return r;}

